## solution

#### using a set

```js
const linkedListCycle = (head) => {
  const nodes = new Set();

  let current = head;
  while (current !== null) {
    if (nodes.has(current)) return true;
    nodes.add(current);
    current = current.next;
  }

  return false;
};
```

- n = number of nodes
- Time: O(n)
- Space: O(n)

#### using two pointers

```js
const linkedListCycle = (head) => {
  let slow = head;
  let fast = head;
  let firstIteration = true;
  while (fast !== null && fast.next !== null) {
    if (slow === fast && !firstIteration) return true;

    slow = slow.next;
    fast = fast.next.next;
    firstIteration = false;
  }

  return false;
};
```

- n = number of nodes
- Time: O(n)
- Space: O(1)

